// UpdateService is the resolver for the updateService field.
func (r *mutationResolver) UpdateService(ctx context.Context, dpfile *graphql.Upload, input model.UpdateServiceInput, removeProfession []*string) (*model.Service, error) {
	// Retrieve the service ID from the context
	serviceIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get service ID: %v", err)
	}
	// Parse the UUID from input
	serviceID, err := uuid.Parse(*serviceIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid service ID: %w", err)
	}

	// Find the existing service
	var service model.Service
	if err := r.DB.Where("id = ?", serviceID).First(&service).Error; err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, fmt.Errorf("service not found with ID: %s", serviceID)
		}
		return nil, fmt.Errorf("failed to fetch service: %w", err)
	}

	// Track whether any updates are needed
	var updateNeeded bool

	// Check and update the service name
	if input.Name != nil && service.Name != *input.Name {
		var existingService model.Service
		if err := r.DB.Where("name = ?", *input.Name).First(&existingService).Error; err == nil {
			return nil, fmt.Errorf("User already exists")
		} else if !errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, fmt.Errorf("failed to check for existing service: %w", err)
		}

		oldSimpleName := strings.ToLower(strings.ReplaceAll(service.Name, " ", "-"))
		oldSimpleName = regexp.MustCompile(`[^a-z0-9-]`).ReplaceAllString(oldSimpleName, "")
		oldBucketName := fmt.Sprintf("s-%s", oldSimpleName[:helper.MinInt(len(oldSimpleName), 10)])

		newSimpleName := strings.ToLower(strings.ReplaceAll(*input.Name, " ", "-"))
		newSimpleName = regexp.MustCompile(`[^a-z0-9-]`).ReplaceAllString(newSimpleName, "")
		newBucketName := fmt.Sprintf("s-%s", newSimpleName[:helper.MinInt(len(newSimpleName), 10)])

		// Inside UpdateService...

		if oldBucketName != newBucketName {
			if service.Dpfile != nil {
				oldURL := *service.Dpfile
				objectPath := strings.TrimPrefix(oldURL, fmt.Sprintf("/minio/%s/", oldBucketName))

				// Ensure new bucket exists before copying
				if err := helper.CreateBucketInMinio(ctx, r.MinIOClient, newBucketName); err != nil {
					return nil, fmt.Errorf("failed to create new bucket: %w", err)
				}

				src := minio.CopySrcOptions{
					Bucket: oldBucketName,
					Object: objectPath,
				}
				dst := minio.CopyDestOptions{
					Bucket: newBucketName,
					Object: objectPath,
				}
				if _, err := r.MinIOClient.CopyObject(ctx, dst, src); err != nil {
					return nil, fmt.Errorf("failed to copy object to new bucket: %w", err)
				}
				if err := r.MinIOClient.RemoveObject(ctx, oldBucketName, objectPath, minio.RemoveObjectOptions{}); err != nil {
					return nil, fmt.Errorf("failed to delete object from old bucket: %w", err)
				}

				newURL := fmt.Sprintf("/minio/%s/%s", newBucketName, objectPath)
				service.Dpfile = &newURL
			}

			// Update gallery profession images
			var galleryProfessions []model.GalleryProfession
			if err := r.DB.Where("service_id = ?", service.ID.String()).Find(&galleryProfessions).Error; err != nil {
				return nil, fmt.Errorf("failed to fetch gallery professions: %w", err)
			}

			for i, gp := range galleryProfessions {
				var updatedUrls pq.StringArray
				var changed bool

				for _, url := range gp.ImageUrls {
					if strings.HasPrefix(url, fmt.Sprintf("/minio/%s/", oldBucketName)) {
						objectPath := strings.TrimPrefix(url, fmt.Sprintf("/minio/%s/", oldBucketName))
						newURL := fmt.Sprintf("/minio/%s/%s", newBucketName, objectPath)
						updatedUrls = append(updatedUrls, newURL)
						changed = true

						src := minio.CopySrcOptions{
							Bucket: oldBucketName,
							Object: objectPath,
						}
						dst := minio.CopyDestOptions{
							Bucket: newBucketName,
							Object: objectPath,
						}
						if _, err := r.MinIOClient.CopyObject(ctx, dst, src); err != nil {
							return nil, fmt.Errorf("failed to copy gallery image: %w", err)
						}
						if err := r.MinIOClient.RemoveObject(ctx, oldBucketName, objectPath, minio.RemoveObjectOptions{}); err != nil {
							return nil, fmt.Errorf("failed to delete old gallery image: %w", err)
						}
					} else {
						updatedUrls = append(updatedUrls, url)
					}
				}

				if changed {
					galleryProfessions[i].ImageUrls = updatedUrls
					if err := r.DB.Save(&galleryProfessions[i]).Error; err != nil {
						return nil, fmt.Errorf("failed to update gallery profession image URLs: %w", err)
					}
				}
			}
		}

		service.Name = *input.Name
		updateNeeded = true
	}

	if input.Type != nil && service.Type != *input.Type {
		service.Type = *input.Type
		updateNeeded = true
	}

	if input.AboutMe != nil && service.AboutMe != input.AboutMe {
		service.AboutMe = input.AboutMe
		updateNeeded = true
	}

	if input.Location != nil && service.Location != input.Location {
		service.Location = input.Location
		updateNeeded = true
	}
	var existingUser model.Service

	// Check and update the service number
	if input.Number != nil && service.Number != *input.Number {
		cleanedNumber := helper.CleanPhoneNumber(*input.Number)
		var existingService model.Service
		if err := r.DB.Where("number = ?", cleanedNumber).First(&existingService).Error; err == nil {
			return nil, fmt.Errorf("a service with the same number already exists")
		} else if !errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, fmt.Errorf("failed to check for existing service: %w", err)
		}

		if err := r.DB.Where("number = ?", cleanedNumber).First(&existingUser).Error; err == nil {

			return nil, fmt.Errorf("User already exists")
		}

		service.Number = cleanedNumber
		updateNeeded = true
	}

	// Check and update the service email
	if input.Email != nil && service.Email != *input.Email {
		var existingService model.Service
		if err := r.DB.Where("email = ? ", input.Email).First(&existingService).Error; err == nil {
			return nil, fmt.Errorf("a service with the same email already exists")
		} else if !errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, fmt.Errorf("failed to check for existing service: %w", err)
		}
		if err := r.DB.Where("email = ?", input.Email).First(&existingUser).Error; err == nil {

			return nil, fmt.Errorf("User already exists")
		}
		service.Email = *input.Email
		updateNeeded = true
	}

	// Check and update the profession
	if input.Profession != nil {
		var professions []string
		for _, profPtr := range input.Profession {
			if profPtr != nil {
				professions = append(professions, *profPtr)
			}
		}

		professionArray := pq.StringArray(professions)
		if !reflect.DeepEqual(service.Profession, professionArray) {
			service.Profession = append(service.Profession, professionArray...)
			updateNeeded = true
		}
	}
	// Remove professions if specified
	if removeProfession != nil {
		professionSet := make(map[string]bool)
		for _, prof := range service.Profession {
			professionSet[prof] = true
		}

		for _, removeProfPtr := range removeProfession {
			if removeProfPtr != nil {
				delete(professionSet, *removeProfPtr)
			}
		}

		var updatedProfessions []string
		for prof := range professionSet {
			updatedProfessions = append(updatedProfessions, prof)
		}

		if !reflect.DeepEqual(service.Profession, pq.StringArray(updatedProfessions)) {
			service.Profession = pq.StringArray(updatedProfessions)
			updateNeeded = true
		}
	}

	// Check and update the password
	if input.Password != nil {
		hashedPassword, err := bcrypt.GenerateFromPassword([]byte(*input.Password), bcrypt.DefaultCost)
		if err != nil {
			return nil, fmt.Errorf("failed to hash password: %w", err)
		}
		hashedPasswordStr := string(hashedPassword)
		if service.Password == nil || *service.Password != hashedPasswordStr {
			service.Password = &hashedPasswordStr
			updateNeeded = true
		}
	}

	// Handle profile picture upload
	if dpfile != nil {
		simpleName := strings.ToLower(strings.ReplaceAll(service.Name, " ", "-"))
		simpleName = regexp.MustCompile(`[^a-z0-9-]`).ReplaceAllString(simpleName, "")
		bucketName := fmt.Sprintf("s-%s", simpleName[:helper.MinInt(len(simpleName), 10)])

		// Ensure the bucket exists
		if err := helper.CreateBucketInMinio(ctx, r.MinIOClient, bucketName); err != nil {
			return nil, err
		}

		// Upload file to MinIO
		fileURL, err := helper.UploadFileToMinio(ctx, r.MinIOClient, bucketName, "dpfile", dpfile)
		if err != nil {
			return nil, fmt.Errorf("failed to upload dpfile %s: %v", dpfile.Filename, err)
		}

		// Only update if the URL is different
		if service.Dpfile == nil || *service.Dpfile != fileURL {
			service.Dpfile = &fileURL
			updateNeeded = true
		}
	}

	// Save only if changes were made
	if updateNeeded {
		if err := r.DB.Save(&service).Error; err != nil {
			return nil, fmt.Errorf("failed to update service: %w", err)
		}
	}

	return &service, nil
}

// GenerateSubDomain is the resolver for the generateSubDomain field.
func (r *mutationResolver) GenerateSubDomain(ctx context.Context, serviceID string) (*model.Service, error) {
	// Generate a subdomain for the service
	uuid, err := uuid.Parse(serviceID)
	if err != nil {
		return nil, fmt.Errorf("invalid service ID: %w", err)
	}

	// Find the service by ID
	var service model.Service
	if err := r.DB.Where("id = ?", uuid).First(&service).Error; err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, fmt.Errorf("service not found with ID: %s", uuid)
		}
		return nil, fmt.Errorf("failed to fetch service: %w", err)
	}

	// Check if service already has a subdomain
	if service.SubDomain != nil && *service.SubDomain != "" {
		// Service already has a subdomain, return the service without changes
		return &service, nil
	}

	// Generate a new subdomain
	clear := strings.ReplaceAll(service.Name, " ", "")
	clear = strings.ReplaceAll(clear, "_", "")
	// Generate a subdomain using gosimple/slug
	subdomain := slug.Make(clear)

	// Ensure the subdomain is unique
	var existingService model.Service
	attempt := 0
	originalSubdomain := subdomain

	for {
		if err := r.DB.Where("sub_domain = ?", subdomain).First(&existingService).Error; err == nil {
			// Subdomain already exists, append a number to make it unique
			attempt++
			subdomain = fmt.Sprintf("%s%d", originalSubdomain, attempt)
		} else if errors.Is(err, gorm.ErrRecordNotFound) {
			// No match found, subdomain is unique
			break
		} else {
			// Unexpected error
			return nil, fmt.Errorf("failed to check for existing subdomain: %w", err)
		}
	}

	// Assign the subdomain to the service
	service.SubDomain = &subdomain

	// Save the updated service to the database
	if err := r.DB.Save(&service).Error; err != nil {
		return nil, fmt.Errorf("failed to save subdomain: %w", err)
	}

	return &service, nil
}

